head.script:
// 테스트 설명, 유효성 값 설정
//  - Header 전용 속성이므로 Header Column(column1) 에만 설정 (설정 영역 옵션 / "Header Column 에서만 동작" 항목 제외)
scwin.tData = {
    "description" : "[column > P > hideCustomFilter]<br/>FilterList 필터의 팝업 목록에 '사용자필터' 항목을 표시할지 설정합니다.",
    "validation" : [
        "GridView 의 useFilterList='true', headerFilter='false' 일때 useFilter='true' 인 Header Column 에서 동작합니다.",
        "true 설정 시, FilterList 필터의 팝업 목록에서 '사용자필터' 항목을 표시하지 않습니다.",
        "true 설정 시, 목록은 '전체선택' 항목과 Column 데이터 항목으로만 구성됩니다.",
        "false 설정 시, FilterList 필터의 팝업 목록에 첫번째 항목으로 '사용자필터' 항목을 표시합니다.",
        "미설정 시, FilterList 필터의 팝업 목록에 첫번째 항목으로 '사용자필터' 항목을 표시합니다.",
        "false 설정 시, '사용자필터' 항목을 선택하면 CustomFilter 팝업창이 표시됩니다.",
        "hideCustomFilter='true' 이어도 showCustomFilter2() 메소드로 CustomFilter 팝업창을 표시할 수 있습니다."
    ]
}



scwin.gVar = {
    // Header Column 별 필터 버튼 클릭 시점에 기록한 필터 상태
    "filterInfo" : {},
    // FilterList 항목 선택으로 CustomFilter 팝업창이 열린 경우 기록
    "customFilterByItem" : ""
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (gdl_boolean 코드 "2" = true, "3" = false)
    con_hideCustomFilter.setValue("2");
    con_useFilterList.setValue("2");
    con_headerFilter.setValue("3");
    con_useFilter.setValue("2");

    // FilterList 항목 클릭으로 CustomFilter 팝업창이 열리는지 기록 (FilterList 는 그리드 밖에 그려질 수 있어 document 에 등록)
    document.addEventListener("click", scwin.recordFilterItemClick, true);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - column1(지역) : 검증 대상 Header Column (hideCustomFilter = con 값)
//  - column2(부서) : 대조 Header Column (hideCustomFilter 미설정)
//  - useFilter 는 column1, column2 에 같은 con 값 적용 / column3(이름) 은 필터 없음
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }
    scwin.gVar.filterInfo = {};
    scwin.gVar.customFilterByItem = "";

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다, gdl_boolean 은 getText() 로 '' / 'true' / 'false' 판단)
    let cHideCustomFilter = con_hideCustomFilter.getText();
    let cUseFilterList = con_useFilterList.getText();
    let cHeaderFilter = con_headerFilter.getText();
    let cUseFilter = con_useFilter.getText();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] hideCustomFilter 는 지역 Header Column 에만 설정, 부서 Header Column 은 미설정(대조)\n[절차] 지역, 부서 Header 의 필터 버튼을 차례로 클릭 (CustomFilter 팝업창이 열리면 닫기 버튼으로 닫음) -> 필터 목록 확인\n지역 FilterList 의 사용자필터 항목 선택 -> 열린 CustomFilter 팝업창 닫기 -> 필터 목록 확인"', '', 'label1');

    // dataList 생성
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "region" : "서울", "dept" : "영업팀", "name" : "김민수" },
        { "region" : "부산", "dept" : "기획팀", "name" : "이영희" },
        { "region" : "서울", "dept" : "개발팀", "name" : "박지훈" },
        { "region" : "대구", "dept" : "영업팀", "name" : "최수진" }
    ], false);

    // GridView 속성
    let attrGrid = '';
    attrGrid += (cUseFilterList === '') ? '' : ' useFilterList="' + cUseFilterList + '"';
    attrGrid += (cHeaderFilter === '') ? '' : ' headerFilter="' + cHeaderFilter + '"';
    // headerFilter=true 이면 필터용 Header 행이 보이도록 초기 표시 설정
    let isHeaderFilter = (cHeaderFilter === 'true');
    if (isHeaderFilter) {
        attrGrid += ' defaultShowHeaderFilter="true"';
    }

    // Header Column 속성
    let attrUseFilter = (cUseFilter === '') ? '' : ' useFilter="' + cUseFilter + '"';
    let attrHide = (cHideCustomFilter === '') ? '' : ' hideCustomFilter="' + cHideCustomFilter + '"';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id=""' + attrGrid + ' style="width:500px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="column1" value="지역"' + attrUseFilter + attrHide + '></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="column2" value="부서"' + attrUseFilter + '></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="column3" value="이름"></w2:column>';
    strTarget += '</w2:row>';
    if (isHeaderFilter) {
        strTarget += '<w2:row style="" id="rowFilter">';
        strTarget += '<w2:filterColumn width="160" style="" id="filterColumn1" value=""></w2:filterColumn>';
        strTarget += '<w2:filterColumn width="160" style="" id="filterColumn2" value=""></w2:filterColumn>';
        strTarget += '<w2:filterColumn width="160" style="" id="filterColumn3" value=""></w2:filterColumn>';
        strTarget += '</w2:row>';
    }
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="region" value=""></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="dept" value=""></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="name" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // FilterList 는 그리드 밖을 누르면 닫히므로, 필터 버튼 클릭 시점의 상태를 기록해 둔다
    target1.render.addEventListener("click", scwin.recordFilterInfo);
}



// 표시 중인 요소인지 확인
scwin.isShown = function (elem) {
    return !!elem && window.getComputedStyle(elem).display !== "none" && elem.getBoundingClientRect().width > 0;
}



// 현재 열린 필터 상태 (FilterList 목록 항목 / CustomFilter 팝업창 표시)
scwin.getFilterState = function () {
    let gridId = target1.id;
    let scrollView = document.getElementById(gridId + "_customFilter_scrollView");
    let customFilter = document.getElementById(gridId + "_customFilter");

    if (scwin.isShown(scrollView) && target1.customFilterList) {
        let arr = [];
        target1.customFilterList.getAllData().forEach(function (row) {
            arr.push("'" + row.id2 + "'");
        });
        return "FilterList 목록 : " + arr.join(" / ");
    }
    if (scwin.isShown(customFilter)) {
        return "CustomFilter 팝업창 표시";
    }
    return "열린 필터 없음";
}



// 필터 버튼 클릭 시 해당 Header Column 의 필터 상태 기록 (목록이 열린 뒤 측정)
scwin.recordFilterInfo = function (e) {
    let elem = e.target;
    let match = (elem && elem.id) ? elem.id.match(/_(column[12])_filter$/) : null;
    if (!match) {
        return;
    }
    let headerID = match[1];
    setTimeout(function () {
        scwin.gVar.filterInfo[headerID] = scwin.getFilterState();
    }, 150);
}



// FilterList 항목 클릭 후 CustomFilter 팝업창이 열렸는지 기록
scwin.recordFilterItemClick = function (e) {
    if (typeof target1 === 'undefined' || !target1) {
        return;
    }
    let list = document.getElementById(target1.id + "_customFilter_list");
    if (!list || !e.target || !list.contains(e.target)) {
        return;
    }
    let row = e.target.closest ? e.target.closest("#" + target1.id + "_customFilter_list > *") : null;
    let rowText = row ? row.textContent.trim() : e.target.textContent.trim();
    setTimeout(function () {
        let customFilter = document.getElementById(target1.id + "_customFilter");
        scwin.gVar.customFilterByItem = "'" + rowText + "' 항목 선택 -> CustomFilter 팝업창 표시 : " + scwin.isShown(customFilter);
    }, 150);
}



// 필터 목록 확인
//  - validation 1 : useFilterList / headerFilter / useFilter 조건별 필터 버튼 유무와 열린 필터 종류
//  - validation 2, 3 : true 설정 시 지역 FilterList 목록 = '전체선택' + 데이터 항목
//  - validation 4, 5 : false / 미설정 시 지역 FilterList 목록 첫번째 = '사용자필터'
//  - validation 6 : '사용자필터' 항목 선택 시 CustomFilter 팝업창 표시
//  - 부서 Column 은 hideCustomFilter 미설정 대조
scwin.btn_checkFilterList_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let fnLbl = function (v) { return v === '' ? "(미설정)" : v; };

    bottom.setReturnValue("hideCustomFilter : " + fnLbl(con_hideCustomFilter.getText())
        + " / useFilterList : " + fnLbl(con_useFilterList.getText())
        + " / headerFilter : " + fnLbl(con_headerFilter.getText())
        + " / useFilter : " + fnLbl(con_useFilter.getText()));

    let arrHeader = [["column1", "지역"], ["column2", "부서(대조)"]];
    for (let i = 0; i < arrHeader.length; i++) {
        let headerID = arrHeader[i][0];
        if (!scwin.isShown(document.getElementById(target1.id + "_" + headerID + "_filter"))) {
            bottom.setReturnValue(arrHeader[i][1] + " : 필터 버튼 없음");
        } else if (scwin.gVar.filterInfo.hasOwnProperty(headerID)) {
            bottom.setReturnValue(arrHeader[i][1] + " " + scwin.gVar.filterInfo[headerID]);
        }
    }

    if (scwin.gVar.customFilterByItem !== "") {
        bottom.setReturnValue(scwin.gVar.customFilterByItem);
    }
}



// validation 7 : showCustomFilter2 로 지역 Header Column 의 CustomFilter 팝업창 표시
scwin.btn_showCustomFilter2_onclick = function () {
    target1.showCustomFilter2("column1");

    let customFilter = document.getElementById(target1.id + "_customFilter");
    wf_body_bottom.getObj("scwin").setReturnValue("showCustomFilter2('column1') -> CustomFilter 팝업창 표시 : " + scwin.isShown(customFilter) + " / 대상 Header Column : " + target1.headerID);
}
